    __TEMP_USE = "0.0",
    mail_title = "Lucien's Return Gift",
    mail_desc = "You are the one who made me realize the sweetness of past time coming back. The best time that I ever experienced, was the special time I shared with you today. So stay by my side, like you always do...",
