    __TEMP_USE = "0.0",
    mail_title = "I Found Out Your Secret",
    mail_desc = "Hey, I just found your \"Valentine's Day Cake\" in the fridge. It would mean nothing to me if I ate it alone. Wait for me, I'll be there in a bit.",
