  [12416] = {
    mail_tag = 1,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Cherished Treasure",
    mail_desc = "Did you know? You are my most cherished treasure in this little treasure hunt. I solemnly swear to you, Miss Chips, I'm not going to miss a single moment with you ever again.",
    mail_effective = "2023/4/9 0:00:00",
    mail_deadline = "2023/4/9 23:59:59",
