  },
  [12482] = {
    mail_tag = 1,
    mail_sender = "Shaw",
    mail_from_npc = 8,
    __TEMP_USE = "0.0",
    mail_title = "New Plan",
    mail_desc = "You're a surprise lover, aren't you? Well, that's interesting. After all, no one loves surprises more than me. Next time on your birthday, I'll give you a surprise you'll never forget. Just wait and see.",
    mail_effective = "2023/6/27 0:00:00",
    mail_deadline = "2023/7/1 23:59:59",
    mail_unlock = "119195,101,3"
  },
  [12610] = {
    mail_tag = 1,
    mail_sender = "Gavin",
    mail_from_npc = 4,
    __TEMP_USE = "0.0",
    mail_title = "After the Party",
    mail_desc = "I never took birthdays too seriously. But I can't help but fall in love with the surprise you have prepared for me. Being in so many people's minds is an overwhelming joy. Thanks for being with me all the way along the journey. Now I know for sure that I am loved, and that love has brought me unshaken confidence.",
    mail_effective = "2023/7/29 0:00:00",
    mail_deadline = "2023/7/29 23:59:59",
    mail_unlock = "119195,101,3"
  },
  [12689] = {
    mail_tag = 1,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Special Program",
    mail_desc = "I've read the proposal for the Halloween-themed show. Well, I'll give you points for creativity, but the \"CEO of LFG wearing a mask and throwing money around the company\" part will not be adopted. ",
    mail_effective = "2022/10/31 00:00:00",
    mail_deadline = "2022/11/1 23:59:59"
  },
  [12690] = {
    mail_tag = 1,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Drama Extras",
    mail_desc = "If you're free tonight, would you like to perform for the Halloween party at the orphanage? The kids want to watch \"Vampire Couple\"... and I want to act with you.",
    mail_effective = "2022/10/31 00:00:00",
    mail_deadline = "2022/11/1 23:59:59"
  },
  [12691] = {
    mail_tag = 1,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Escape Game",
    mail_desc = "Why don't we challenge the new horror game this year, instead of the usual ghost storytelling contest? I've ordered a new handle especially for Miss Chips! But... can we play some festive music during the game?",
    mail_effective = "2022/10/31 00:00:00",
    mail_deadline = "2022/11/1 23:59:59"
  },
  [12692] = {
    mail_tag = 1,
    mail_sender = "Gavin",
    mail_from_npc = 4,
    __TEMP_USE = "0.0",
    mail_title = "Lego Parade",
    mail_desc = "I've got some Legos. Together with the ones you gave me, we can throw a big Halloween party at home just for us. It must be more fun than the parade on the street.",
    mail_effective = "2022/10/31 00:00:00",
    mail_deadline = "2022/11/1 23:59:59"
  },
  [12693] = {
    mail_tag = 1,
    mail_sender = "Shaw",
    mail_from_npc = 8,
    __TEMP_USE = "0.0",
    mail_title = "Work Pass for Haunted House",
    mail_desc = "Aren't you satisfied with your Halloween makeup? I've got a haunted house work pass. Why don't we go and scare those milksops?",
    mail_effective = "2022/10/31 00:00:00",
    mail_deadline = "2022/11/1 23:59:59"
  },
  [12723] = {
    mail_tag = 1,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Time of Longing",
    mail_desc = "What you have done for me this year has touched me deeply. I feel like we now share a bond that transcends our boundaries and merges us as one. You will always be the most reassuring presence by my side, from this day until the end of days, and that is the most precious gift I have ever received.",
    mail_effective = "2023/11/15  0:00:00",
    mail_deadline = "2023/11/15  23:59:59",
    mail_unlock = "119195,101,3"
  },
  [12774] = {
    mail_tag = 1,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "I'll Always Be Here",
    mail_desc = "For that certain someone who was so excited that she didn't even get a wink of sleep, I'll allow you to sleep in. Don't get so worked up next time. We have the rest of our lives to enjoy every anniversary together.",
    mail_effective = "2024/03/20 00:00:00",
    mail_deadline = "2024/03/21 23:59:59",
    mail_unlock = "119195,101,3"
  },
  [12775] = {
    mail_tag = 1,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Heart of the Soul",
    mail_desc = "Some say time is a crucible that forges the strongest love. Then as faithfully as these five years have unfolded, so too shall I dedicate every ensuing moment, until our very souls are imbued with this profound bond.",
    mail_effective = "2024/03/20 00:00:00",
    mail_deadline = "2024/03/21 23:59:59",
    mail_unlock = "119195,101,3"
  },
  [12776] = {
    mail_tag = 1,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Even More Than Today",
    mail_desc = "When I held Miss Chips' hands this morning, I thought to myself that I couldn't possibly love you any more than I do today. But on second thought, I've been thinking that every day for the past five years.",
    mail_effective = "2024/03/20 00:00:00",
    mail_deadline = "2024/03/21 23:59:59",
    mail_unlock = "119195,101,3"
  },
  [12777] = {
    mail_tag = 1,
    mail_sender = "Gavin",
    mail_from_npc = 4,
    __TEMP_USE = "0.0",
    mail_title = "A Distant Tomorrow",
    mail_desc = "We have forged many meaningful memories together. But that's far from enough. I won't rest until we have experienced every beauty that life has to offer.",
    mail_effective = "2024/03/20 00:00:00",
    mail_deadline = "2024/03/21 23:59:59",
    mail_unlock = "119195,101,3"
  },
  [12778] = {
    mail_tag = 1,
    mail_sender = "Shaw",
    mail_from_npc = 8,
    __TEMP_USE = "0.0",
    mail_title = "Call Me Anytime",
    mail_desc = "Why are you so focused on this anniversary thing? It's not like I've ever missed a single one. Don't worry. I'll be always by your side.",
    mail_effective = "2024/03/20 00:00:00",
    mail_deadline = "2024/03/21 23:59:59",
    mail_unlock = "119195,101,3"
  },
  [12792] = {
