    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Chocolate & Disguise",
    mail_desc = "Even if you dress up as Santa Claus and put a white beard on your face, delivering presents at LFG, I can still recognize you instantly. Well, the packaging is unsatisfactory, to say the least, but handmade chocolate doesn't taste that bad, I'll give you that.",
    mail_effective = "2022/12/24 18:00:00",
