    __TEMP_USE = "0.0",
    mail_title = "Beautiful Happiness",
    mail_desc = "There are a lot of happy people in this world, but I know for a fact that a Kiro with you by his side is the happiest man alive. As long as you're with me, I feel like the luckiest person in this entire world, now and forever.",
