    mail_desc = "Don't buy so much useless stuff just because you get tempted. Just because an item is on sale doesn't mean that you need it.",
    mail_number = 78,
    mail_effective = "2022/02/17 05:00:00",
    mail_deadline = "2022/2/18 4:59:59"
  },
  [91079] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 79",
    mail_desc = "Don't forget there's a meeting this afternoon. And also don't forget to check in today.",
    mail_number = 79,
    mail_effective = "2022/02/18 05:00:00",
    mail_deadline = "2022/2/19 4:59:59"
  },
  [91080] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 80",
    mail_desc = "Rather than reminisce about the past, why don't we do the most worthwhile things all over again?",
    mail_number = 80,
    mail_effective = "2022/02/19 05:00:00",
    mail_deadline = "2022/2/20 4:59:59"
  },
  [91081] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 81",
    mail_desc = "Hitting refresh all day on the tracking page won't make your package arrive any sooner, but you can eat the meal you reserved today an hour earlier.",
    mail_number = 81,
    mail_effective = "2022/02/20 05:00:00",
    mail_deadline = "2022/2/21 4:59:59"
  },
  [91082] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 82",
    mail_desc = "I'm not going to play this boring game of assumptions. What if I'd never met you? I wouldn't allow such a thing to occur.",
    mail_number = 82,
    mail_effective = "2022/02/21 05:00:00",
    mail_deadline = "2022/2/22 4:59:59"
  },
  [91083] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 83",
    mail_desc = "Just because I decide something doesn't mean there's no room for improvement. It depends on what thing of value you want to give in exchange.",
    mail_number = 83,
    mail_effective = "2022/02/22 05:00:00",
    mail_deadline = "2022/2/23 4:59:59"
  },
  [91084] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 84",
    mail_desc = "I see a photo with you and Pudding in it. Neither the person or the cat has changed. Good stuff.",
    mail_number = 84,
    mail_effective = "2022/02/23 05:00:00",
    mail_deadline = "2022/2/24 4:59:59"
  },
  [91085] = {
