    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 85",
    mail_desc = "If I get another insipid message from you about helping you get a price cut on some online group buy scheme, the only thing that will get cut is funding for your next project.",
    mail_number = 85,
