    mail_deadline = "2022/2/25 4:59:59"
  },
  [91086] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 86",
    mail_desc = "When I passed by your office yesterday, you weren't there. But the level of mess on your desk surpassed my imagination.",
    mail_number = 86,
    mail_effective = "2022/02/25 05:00:00",
    mail_deadline = "2022/2/26 4:59:59"
  },
  [91087] = {
