    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 87",
    mail_desc = "I had someone bring back more of those coffee beans that you liked last time. Remember to come pick them up tonight.",
