    mail_effective = "2022/02/27 05:00:00",
    mail_deadline = "2022/2/28 4:59:59"
  },
  [91089] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 89",
    mail_desc = "I just gave you a little pinch on the back of your neck. Why did your eyes go as wide as Pudding's?",
