    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 90",
    mail_desc = "A certain someone's check-in times have been getting later and later these past few days. As you near the finish line, that's when you have to keep your foot on the gas the most.",
    mail_number = 90,
    mail_effective = "2022/03/01 05:00:00",
    mail_deadline = "2022/3/2 4:59:59"
  },
  [91091] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 91",
    mail_desc = "Ancient peoples had spring fever because in spring there's a lot of work to be done. Whereas I feel a certain someone's spring fever is because she hasn't got enough reports to write.",
    mail_number = 91,
    mail_effective = "2022/03/02 05:00:00",
    mail_deadline = "2022/3/3 4:59:59"
  },
  [91092] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 92",
    mail_desc = "It boggles my mind the fact that someone thinks she can win the lottery when she hasn't even won a free coke from a bottlecap sweepstakes more than a few times.",
    mail_number = 92,
    mail_effective = "2022/03/03 05:00:00",
    mail_deadline = "2022/3/4 4:59:59"
  },
  [91093] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 93",
    mail_desc = "...I was just making fun of you yesterday, and now you've won a Tier 5 reward. Isn't that just the luck of the moron?",
    mail_number = 93,
    mail_effective = "2022/03/04 05:00:00",
    mail_deadline = "2022/3/5 4:59:59"
  },
  [91094] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 94",
    mail_desc = "I might believe that you're lying down because you're brainstorming -- if you hadn't fallen asleep on the sofa last night.",
    mail_number = 94,
    mail_effective = "2022/03/05 05:00:00",
    mail_deadline = "2022/3/6 4:59:59"
  },
  [91095] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 95",
    mail_desc = "Sometimes I go back over check-ins from the past and reminisce about things this moron has done.",
    mail_number = 95,
    mail_effective = "2022/03/06 05:00:00",
    mail_deadline = "2022/3/7 4:59:59"
  },
  [91096] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 96",
    mail_desc = "If you have time to write a novel-length proposal, perhaps the time would be better spent just putting the project in motion.",
    mail_number = 96,
    mail_effective = "2022/03/07 05:00:00",
    mail_deadline = "2022/3/8 4:59:59"
  },
  [91097] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 97",
    mail_desc = "When you do ordinary exercise, suddenly you're so tired you can't move. But when the delivery arrives, you're the fastest alive.",
    mail_number = 97,
    mail_effective = "2022/03/08 05:00:00",
    mail_deadline = "2022/3/9 4:59:59"
  },
  [91098] = {
    mail_tag = 2,
    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 98",
    mail_desc = "Every time you say surprise, it's a test of a person's ability to handle stress.",
    mail_number = 98,
    mail_effective = "2022/03/09 05:00:00",
    mail_deadline = "2022/3/10 4:59:59"
  },
  [91099] = {
