    mail_sender = "Victor",
    mail_from_npc = 1,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 99",
    mail_desc = "Don't worry over the fact that the checking in will soon come to an end. If you want, I can extend this childish game indefinitely for you.",
    mail_number = 99,
