    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 8",
    mail_desc = "I quite enjoy this feeling of being in a warm restaurant with you on a frigid day, eating a piping hot bowl of noodles.",
