    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 16",
    mail_desc = "In my book today I found a leaf bookmark with a smiley face drawn on it. Did you secretly put it back in after borrowing it last time?",
