    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 17",
    mail_desc = "You always say I'm your \"\"mentor\"\" but in point of fact, I learn a lot being around you.",
    mail_number = 17,
    mail_effective = "2021/12/18 05:00:00",
    mail_deadline = "2021/12/19 04:59:59"
  },
  [92018] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 18",
    mail_desc = "Are you up? I'm on my way back from the research center and just happen to be passing by that soup dumplings place you like. I could bring some back for you.",
    mail_number = 18,
    mail_effective = "2021/12/19 05:00:00",
    mail_deadline = "2021/12/20 04:59:59"
  },
  [92019] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 19",
    mail_desc = "My research projects lately have me up at all hours, but no matter what, I will remember my promises to you.",
    mail_number = 19,
    mail_effective = "2021/12/20 05:00:00",
    mail_deadline = "2021/12/21 04:59:59"
  },
  [92020] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 20",
    mail_desc = "A colleague told me about a used book store. Want to go browse it together? Perhaps we might find some unexpected treasures.",
    mail_number = 20,
    mail_effective = "2021/12/21 05:00:00",
    mail_deadline = "2021/12/22 04:59:59"
  },
  [92021] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 21",
    mail_desc = "A little alley cat is stretching out lazily in the autumn sun, and it's making me suddenly want to sunbathe with you.",
    mail_number = 21,
    mail_effective = "2021/12/22 05:00:00",
    mail_deadline = "2021/12/23 04:59:59"
  },
  [92022] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 22",
    mail_desc = "The air is a bit stifling. I'm just waiting for a rain to come and wash away this lingering fall heat. Aren't you?",
    mail_number = 22,
    mail_effective = "2021/12/23 05:00:00",
    mail_deadline = "2021/12/24 04:59:59"
  },
  [92023] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 23",
    mail_desc = "I always love the gifts you give every year, but of course my favorite gift is being able to see you as soon as I open my eyes.",
    mail_number = 23,
    mail_effective = "2021/12/24 05:00:00",
    mail_deadline = "2021/12/25 04:59:59"
  },
  [92025] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 25",
    mail_desc = "I always worry about fighting the crowds when going out during this time, but with you by my side, it doesn't seem that daunting anymore.",
    mail_number = 25,
    mail_effective = "2021/12/26 05:00:00",
    mail_deadline = "2021/12/27 4:59:59"
  },
  [92026] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 26",
    mail_desc = "You said you like the scenery here. I do too. I like this scenery, with you in it.",
    mail_number = 26,
    mail_effective = "2021/12/27 05:00:00",
    mail_deadline = "2021/12/28 4:59:59"
  },
  [92027] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 27",
