    mail_effective = "2021/12/28 05:00:00",
    mail_deadline = "2021/12/29 4:59:59"
  },
  [92028] = {
    mail_tag = 2,
    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 28",
    mail_desc = "It's not that I've never come here before, but this time my heart is in a different place. I think it must be because of you.",
    mail_number = 28,
    mail_effective = "2021/12/29 05:00:00",
    mail_deadline = "2021/12/30 4:59:59"
  },
  [92029] = {
