    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 29",
    mail_desc = "If you're reluctant to leave this place, then let's make plans to revisit our old haunt next time.",
