    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 45",
    mail_desc = "These past few days, I've been unable to sleep soundly due to the noise of the frigid winds beating against the windows. But I also can't blame them for their wanton winter ways.",
