    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 84",
    mail_desc = "After yesterday's \"\"unhappiness\"\", I've prepared a double dose of \"\"happiness\"\" today. Can I share one with you?",
