    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 85",
    mail_desc = "I have to go out of town for a meeting today. It's that city up North that you posted about in your Moments last year. Perhaps I can follow in your footsteps and check in at all those spots too.",
