    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 86",
    mail_desc = "I woke up today to find that it has snowed in this city. I didn't want to take in the first snow of the year all by myself, so I'm sharing it with you right away.",
