    mail_sender = "Lucien",
    mail_from_npc = 2,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 100",
    mail_desc = "One hundred days is too short for me. Even if we hadn't done this activity, I certainly wouldn't stop at just one hundred days with you.",
