  },
  [93001] = {
    mail_tag = 2,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 1",
    mail_desc = "The happiest thing in my whole life is starting each day with you. With you, every day is special.",
    mail_number = 1,
    mail_effective = "2021/12/02 05:00:00",
    mail_deadline = "2021/12/03 04:59:59"
  },
  [93002] = {
    mail_tag = 2,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 2",
    mail_desc = "Every time Friday rolls around, I feel both excited and tantalized. Should we celebrate the start of the weekend with some barbecue?",
    mail_number = 2,
    mail_effective = "2021/12/03 05:00:00",
    mail_deadline = "2021/12/04 04:59:59"
  },
  [93003] = {
    mail_tag = 2,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 3",
    mail_desc = "Happiness is a Saturday when you can sleep in. Did you have good dreams about me?",
    mail_number = 3,
    mail_effective = "2021/12/04 05:00:00",
    mail_deadline = "2021/12/05 04:59:59"
  },
  [93004] = {
    mail_tag = 2,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 4",
    mail_desc = "I'm giving half of my luck and happiness to you, Miss Chips. I just know you'll have a pleasant day.",
    mail_number = 4,
    mail_effective = "2021/12/05 05:00:00",
    mail_deadline = "2021/12/06 04:59:59"
  },
  [93005] = {
    mail_tag = 2,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 5",
    mail_desc = "I had so much fun with you yesterday, Miss Chips, that I almost overslept today, and then Savin lectured me for a long time... Although I didn't forget our hundred days check-in!",
    mail_number = 5,
    mail_effective = "2021/12/06 05:00:00",
    mail_deadline = "2021/12/07 04:59:59"
  },
  [93006] = {
    mail_tag = 2,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 6",
    mail_desc = "People will only ever see a handful of eclipses and blood moons in their lives. I hope all these special moments are with you by my side.",
    mail_number = 6,
    mail_effective = "2021/12/07 05:00:00",
    mail_deadline = "2021/12/08 04:59:59"
  },
  [93007] = {
    mail_tag = 2,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 7",
    mail_desc = "I think these cartoons from when we were kids still hold up. Next time, let's watch them again!",
    mail_number = 7,
    mail_effective = "2021/12/08 05:00:00",
    mail_deadline = "2021/12/09 04:59:59"
  },
  [93008] = {
    mail_tag = 2,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 8",
    mail_desc = "I want to watch a movie with you, draw the curtains and curl up together, just the two of us. Let's make it happen tonight!",
    mail_number = 8,
    mail_effective = "2021/12/09 05:00:00",
    mail_deadline = "2021/12/10 04:59:59"
  },
  [93009] = {
    mail_tag = 2,
    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 9",
    mail_desc = "Today's a day for going out! Even if it was colder, that wouldn't stop me from wanting to see you.",
    mail_number = 9,
    mail_effective = "2021/12/10 05:00:00",
    mail_deadline = "2021/12/11 04:59:59"
  },
  [93010] = {
