    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 10",
    mail_desc = "Last night the chicken from that fried chicken place sent me a dream, asking me to go buy it. Today, let's make its wish come true!",
    mail_number = 10,
    mail_effective = "2021/12/11 05:00:00",
    mail_deadline = "2021/12/12 04:59:59"
