    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 11",
    mail_desc = "I just made a huge sneeze! Is it because I'm cold, or because you're thinking of me...?",
    mail_number = 11,
    mail_effective = "2021/12/12 05:00:00",
    mail_deadline = "2021/12/13 04:59:59"
  },
  [93012] = {
