    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 12",
    mail_desc = "Getting off work and getting in a car to go see you fills me with a feeling of freedom!",
    mail_number = 12,
    mail_effective = "2021/12/13 05:00:00",
    mail_deadline = "2021/12/14 04:59:59"
