    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 14",
    mail_desc = "This morning, a sparrow perched on my window sill. It was super fat! It must be so nice to be an animal. Every winter they can pack on the pounds without any guilt.",
