    mail_sender = "Kiro",
    mail_from_npc = 3,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 15",
    mail_desc = "They say today is a good day for ghost stories. Miss Chips, if you're too scared to sleep at night, just come over to my place. We won't be scared if we're together!",
