    mail_sender = "Shaw",
    mail_from_npc = 8,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 1",
    mail_desc = "Are you saying starting a competition with me isn't the most exciting thing you're doing all day? Don't try to deny it.",
