    mail_sender = "Shaw",
    mail_from_npc = 8,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 2",
    mail_desc = "I've got my eye on you now. No slacking off, and don't even think of trying to run away.",
