    mail_sender = "Shaw",
    mail_from_npc = 8,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 3",
    mail_desc = "You woke up early for a change yesterday, and now today you can't get up? Do I need to think of a way to wake you up?",
