    mail_sender = "Shaw",
    mail_from_npc = 8,
    __TEMP_USE = "0.0",
    mail_title = "Hundred Days Together - Day 4",
    mail_desc = "Wakey-wakey! What time is it? If you just spend your whole weekend staying up late and sleeping in, isn't that a waste?",
